import prisma from "../db.server";

export const action = async ({ request }) => {
  try {
    // только POST
    if (request.method !== "POST") {
      return new Response("Method not allowed", { status: 405 });
    }

    const body = await request.json();

    const shop = "terrea-dev-store.myshopify.com";
    const customerId = body.customer?.id?.toString();
    const orderId = String(body.id);
    const totalPrice = parseFloat(body.total_price || "0");

    // если нет клиента — пропускаем
    if (!customerId) {
      return new Response("OK");
    }

    // 💰 начисление (10% от заказа)
    const points = Math.floor(totalPrice * 0.1);

    /* ================================
       ❗ ПРОВЕРКА: уже начисляли?
    ================================= */
    const existingTx = await prisma.pointsTransaction.findFirst({
      where: {
        orderId,
        type: "earn",
      },
    });

    if (existingTx) {
      console.log("⚠️ Already processed order:", orderId);
      return new Response("Already processed");
    }

    /* ================================
       WALLET
    ================================= */
    let wallet = await prisma.wallet.findFirst({
      where: {
        customerId,
        shop,
      },
    });

    if (!wallet) {
      wallet = await prisma.wallet.create({
        data: {
          shop,
          customerId,
          balance: 0,
          totalSpent: 0,
        },
      });
    }

    /* ================================
       🔥 АТОМАРНО: баланс + транзакция
    ================================= */
    await prisma.$transaction([
      prisma.wallet.update({
        where: { id: wallet.id },
        data: {
          balance: {
            increment: points, // ✅ правильно
          },
          totalSpent: {
            increment: totalPrice,
          },
        },
      }),

      prisma.pointsTransaction.create({
        data: {
          walletId: wallet.id,
          shop,
          customerId,
          orderId,
          type: "earn",
          amount: points, // ✅ ВАЖНО (не points!)
          description: "Order reward",
        },
      }),
    ]);

    console.log(`✅ Points added: +${points} (order ${orderId})`);

    return new Response(JSON.stringify({ success: true }), {
      status: 200,
    });

  } catch (error) {
    console.error("❌ WEBHOOK ERROR:", error);
    return new Response("Error", { status: 500 });
  }
};